#!/usr/bin/env python3
"""Encode a fixed 600-frame candidate generated by independent_batch.py."""
import argparse
import subprocess
from pathlib import Path


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--case', required=True)
    parser.add_argument('--frames', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    if args.output.exists():
        raise SystemExit(f'Refusing to overwrite {args.output}')
    images = [args.frames / f'{args.case}_{i:04d}.png' for i in range(600)]
    missing = [str(p) for p in images if not p.is_file() or not p.stat().st_size]
    if missing:
        raise SystemExit(f'Missing or empty input frame: {missing[0]}')
    args.output.parent.mkdir(parents=True, exist_ok=True)
    cmd = ['ffmpeg', '-hide_banner', '-loglevel', 'warning', '-n', '-framerate', '30',
           '-start_number', '0', '-i', str(args.frames / f'{args.case}_%04d.png'),
           '-frames:v', '600', '-c:v', 'libx264', '-preset', 'fast', '-crf', '0',
           '-pix_fmt', 'yuv420p', '-g', '600', '-bf', '0', '-sc_threshold', '0',
           '-movflags', '+faststart', str(args.output)]
    subprocess.run(cmd, check=True)


if __name__ == '__main__':
    main()
